WITH filtered_products AS (SELECT * FROM products WHERE supplier_id IS NOT NULL AND launch_date <= '2024-09-01'), PriceBucketSummary AS (SELECT CASE WHEN price >= 1040 THEN 'high' WHEN price >= 440 THEN 'mid' ELSE 'low' END AS price_bucket, COUNT(DISTINCT cost) AS unique_categorys, COUNT(CASE WHEN brand = 'Umbrella' THEN 1 END) AS umbrella_count FROM filtered_products GROUP BY CASE WHEN price >= 1040 THEN 'high' WHEN price >= 440 THEN 'mid' ELSE 'low' END) SELECT price_bucket, unique_categorys, umbrella_count FROM PriceBucketSummary ORDER BY 3;
